import IUser from "interface/user";
import IAddress from "interface/address";
import ICompany from "interface/company";
import { Data } from "data/data";
import { DisplayUserInfo } from "./displayuserinfo";

let username : Element | null = document.querySelector(".user-name") as HTMLElement;
const companyname = document.querySelector(".company-name") as HTMLElement;
const bio = document.querySelector(".bio") as HTMLElement;
const Email = document.getElementById("email") as HTMLElement;
const contactItem = document.querySelector(".contact-item") as HTMLElement;
const child = contactItem?.querySelector("a") as HTMLElement;

const contact = document.getElementById("contact-item");

console.log(username)
interface userDetail extends IUser, ICompany, IAddress {}


let appContainer : HTMLElement | null =  null ;


export class User{
    
    getAppContainer() : HTMLElement | null{
        if(!appContainer){
            appContainer = document.getElementById('app');
            if (!appContainer) {
                console.error('Error: App container element with ID "app" not found in the DOM.');
                return null;
            }
        }

        return appContainer ;
    }
    
    
    handlePageRender(path:string) {
    const container = this.getAppContainer();
    if (!container)
        return; // Exit if app container is not found
    // Trim leading/trailing slashes for consistent path matching
    const cleanPath = path.replace(/^\/|\/$/g, '');
    if (cleanPath === '' || cleanPath === 'index.html') {
        const users  = new DisplayUserInfo();
        users.DisplayUsers();
        // Render the user list for the root path
       // renderUserList();
    } else if (cleanPath.startsWith('user/')) {
        // Extract user ID from the path (e.g., "user/1" -> 1)
        const parts = cleanPath.split('/');
        const userId = parseInt(parts[1], 10); // Ensure base 10 for parsing
        if (!isNaN(userId)) {
     //       renderUserDetail(userId);
        }
        else {
            // Handle invalid user ID in URL
            container.innerHTML = `
                <div class="message-box orange-alert">
                    <h1>Invalid User ID</h1>
                    <p>The user ID in the URL is not a valid number.</p>
                    <button id="backToListBtn" class="btn btn-orange message-button">
                        Go to List
                    </button>
                </div>
            `;
            document.getElementById('backToListBtn')?.addEventListener('click', () => {
               this. navigateTo('/');
            });
        }
    }
    else {
        // Handle 404 - Page not found
        container.innerHTML = `
            <div class="message-box gray-info">
                <h1>404 - Page Not Found</h1>
                <p>The page at "${path}" does not exist.</p>
                <button id="backToHomeBtn" class="btn btn-gray message-button">
                    Go to Home
                </button>
            </div>
        `;
        document.getElementById('backToHomeBtn')?.addEventListener('click', () => {
           this. navigateTo('/');
        });
    }

}

   private displayUserInfo = (user: userDetail) :void =>  {
    if (username) username.textContent = user.username;
   if(companyname) companyname.textContent = user.name ;
    if(bio) bio.textContent = user.catchPhrase;
    if(Email) Email.textContent = user.email ;
 
    }

    getQueryParam(param : string) :string | null {
        const urlParams = new URLSearchParams(window.location.search);
        return urlParams.get(param);
    }


    public LoaduserInfo = async (userid: number): Promise<void> => {
       
        const fetchdata = new Data();
        const userInfo = await fetchdata.FetchSingleObj<userDetail>("users", userid);
        const userId = this.getQueryParam(`${userInfo!.id}`);
        if(!userId){
            const element = document.createElement("h2");
            element.textContent = "user is not found"            
        }
        if (userInfo ) {
            console.log( "email" ,userInfo.email)
            window.location.hash = `../../pages/user/user.html/${userId}`
            this.displayUserInfo(userInfo);
            //username!.innerHTML = "Load" ;
          
        }else {
          console.log("user is not found");   
        }

    }

   navigateTo(path :string) {
    history.pushState(null, '', path); // Update URL without reloading the page
    this.handlePageRender(path); // Render the new content
    
   }
   

   poststate(): void {
    
    window.addEventListener('popstate', () => {
       this.handlePageRender(location.pathname);
    });
  }
/**
 * Initial page render when the script loads.
 * This ensures the correct content is displayed when the page is first accessed.
 */
 load(): void{ 
    
    document.addEventListener('DOMContentLoaded', () => {
    // Initialize appContainer when the DOM is ready
    appContainer = document.getElementById('app');
    this.handlePageRender(location.pathname);
    });
}

};
